describe('Breadcrumb Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to the base of your application
    });

    it('should display the correct breadcrumb for the homepage', () => {
        cy.get('.breadcrumb').should('exist');
        cy.get('.breadcrumb').should('contain', 'Home');
    });

    it('should update the breadcrumb when navigating to a subpage', () => {
        cy.get('a[href="/subpage"]').click(); // Adjust the selector to match your subpage link
        cy.get('.breadcrumb').should('exist');
        cy.get('.breadcrumb').should('contain', 'Home');
        cy.get('.breadcrumb').should('contain', 'Subpage'); // Adjust to match the subpage name
    });
});
